#!/usr/bin/env bash
# The world every evaluate-session case wakes up in.
#
# The skill grades a session transcript, and the eval sandbox has none: its home
# is empty and the case's own run is the only session in it. So the fixture
# brings three, generated by the calibration's make-sessions.py and embedded
# here by scripts/sync-eval-fixtures.sh so the two cannot drift:
#
#   sessions/bad-session.jsonl       fifteen prompts, five costs — gradable
#   sessions/ordinary-session.jsonl  the same project driven properly
#   sessions/short-session.jsonl     three prompts, below the five-prompt floor
#   sessions/shipping-tracker/       the project they ran in
#
# The whole workspace is a git repo with a feature branch, so the near-miss
# prompts ("review this branch") have a referent and are a fair test rather
# than a trick.
set -eu

git init -q -b main .
git config user.email eval@example.invalid
git config user.name  Eval
git config commit.gpgsign false

mkdir -p sessions
python3 - --out sessions > /dev/null <<'PY'
@EMBED session-calibration/make-sessions.py
PY

commit() { # date, message
  git add -A
  GIT_AUTHOR_DATE="$1" GIT_COMMITTER_DATE="$1" git commit -qm "$2"
}

commit '2026-09-19T08:00:00' 'Initial commit'

git checkout -qb cache-ttl
cat > sessions/shipping-tracker/src/cache.js <<'EOF'
// Entries expire after ttl milliseconds.
const store = new Map();
function get(key) {
  const hit = store.get(key);
  if (hit && hit.expires > Date.now()) return hit.value;
  return undefined;
}
function set(key, value, ttl) {
  store.set(key, { value, expires: Date.now() + ttl });
}
module.exports = { get, set };
EOF
commit '2026-09-19T10:00:00' 'Expire cache entries after a TTL'
